 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0 for _ in range(w)] for _ in range(h)]
    occupied = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    # Mark disjoint complete 2x2 blocks first; these are the color-1 motifs.
    claimed = set()
    for r in range(h - 1):
        for c in range(w - 1):
            block = {(r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)}
            if block <= occupied and not (block & claimed):
                for rr, cc in block:
                    out[rr][cc] = 1
                claimed |= block
    # Remaining runs form the three oriented residual pieces: upper/right=4,
    # lower/left=3, and central/lower=2.
    for r, c in occupied - claimed:
        if r <= 1 and c >= 2:
            out[r][c] = 4
        elif c <= 1 and r >= 1:
            out[r][c] = 3
        else:
            out[r][c] = 2
    return out

