    assert sum(x == 1 for row in transform(g) for x in row) == 8
    assert sum(x == 2 for row in transform(g) for x in row) + sum(x == 3 for row in transform(g) for x in row) + sum(x == 4 for row in transform(g) for x in row) == 4
  ",
 "cross_profile": false
}

